def policy(obs,P):
    x,y,vx,vy,angle,ang_v,ll,lr = obs[0],obs[1],obs[2],obs[3],obs[4],obs[5],obs[6],obs[7]
    if ll>0.5 and lr>0.5:
        if abs(vx)<P['vx_land'] and abs(vy)<P['vy_land'] and abs(angle)<P['ang_land']:
            return 0
        if abs(angle)<P['ang_land2']:
            return 2
    if vy < P['vy_thresh']:
        if y < P['y_low']:
            if angle < P['ang_neg']:
                return 1
            if angle > P['ang_pos']:
                return 3
            if vx > P['vx_pos_high']:
                return 1
            if vx < P['vx_neg_high']:
                return 3
            return 2
        else:
            if vy < P['vy_fast']:
                return 0
            if vx < P['vx_neg']:
                return 0
            return 0
    else:
        if vx <= P['vx_small']:
            if x <= P['x_thresh']:
                if y <= P['y_mid']:
                    return 3
                return 0
            return 1
        else:
            if lr>0.5 or ll>0.5:
                if vx <= P['vx_land2']:
                    return 0
                return 1
            if angle <= P['ang_small']:
                return 1
            return 3
